css:
.pc { display: flex; flex-direction: column; height: 100%; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); overflow: hidden; color: inherit; text-decoration: none; transition: box-shadow var(--hcm-dur) var(--hcm-ease), transform var(--hcm-dur) var(--hcm-ease); }
.pc:hover { box-shadow: var(--hcm-shadow); transform: translateY(-3px); color: inherit; }
.pc__media { display: block; overflow: hidden; }
.pc__media img { display: block; width: 100%; height: 190px; object-fit: cover; transition: transform 380ms var(--hcm-ease); }
.pc:hover .pc__media img { transform: scale(1.04); }
.pc__body { display: flex; flex-direction: column; gap: 10px; padding: 20px; flex: 1; }
.pc__meta { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; }
.pc__cat { font: 700 11px/1.2 var(--font-body); letter-spacing: .1em; text-transform: uppercase; color: #fff; background: var(--accent); padding: 3px 8px; border-radius: var(--radius-chip); }
.pc__date { font-size: 13px; color: var(--muted); }
.pc__t { font: 700 22px/1.12 var(--font-heading); color: var(--accent); }
.pc__x { font-size: 14px; line-height: 1.6; color: var(--hcm-body); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.pc__by { font-size: 13px; color: var(--muted); margin-top: auto; }
.pc__by strong { color: var(--hcm-navy); }
.pc__more { margin-top: auto; font: 700 16px/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; color: var(--accent); }
.pc--wide { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); }
.pc--wide .pc__media { padding: 24px; display: flex; align-items: center; justify-content: center; }
.pc--wide .pc__media img { height: auto; max-height: 420px; object-fit: contain; }
.pc--wide .pc__body { padding: clamp(28px, 4vw, 48px); gap: 14px; justify-content: center; }
.pc--wide .pc__t { font-size: clamp(28px, 3.4vw, 40px); line-height: 1.05; text-transform: uppercase; }
.pc--wide .pc__x { font-size: 16px; -webkit-line-clamp: 4; }
.pc--row { display: block; background: none; border: 0; border-bottom: 1px solid rgb(255 255 255 / 20%); border-radius: 0; }
.pc--row:hover { box-shadow: none; transform: none; }
.pc--row .pc__body { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); gap: 12px 40px; padding: 26px 0; }
.pc--row .pc__meta { grid-column: 1; }
.pc--row .pc__t { grid-column: 1; font-size: 26px; color: #fff; }
.pc--row .pc__x { grid-column: 2; grid-row: 1 / span 2; font-size: 15px; color: var(--hcm-on-navy); }
.pc--row .pc__more { grid-column: 2; color: #fff; }
.pc--row .pc__cat { background: #fff; color: var(--accent); }
.pc--row .pc__date { color: var(--hcm-on-navy-2); }
@media (max-width: 760px) { .pc--row .pc__x, .pc--row .pc__more { grid-column: 1; grid-row: auto; } }
